import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";

export default function DriverDetails() {
  const { id } = useParams();
  const [driver, setDriver] = useState<any>(null);

  useEffect(() => {
    axios.get(`http://localhost:5000/api/drivers/${id}`).then(res => setDriver(res.data));
  }, [id]);

  const handleDelete = async () => {
    await axios.delete(`http://localhost:5000/api/drivers/${id}`);
    alert("Driver deleted");
  };

  return driver ? (
    <div style={{ padding: "20px" }}>
      <h2>Driver Details</h2>
      <p><strong>Name:</strong> {driver.name}</p>
      <p><strong>Email:</strong> {driver.email}</p>
      <p><strong>Status:</strong> {driver.status}</p>
      <button onClick={handleDelete} style={{ padding: "10px 20px", backgroundColor: "red", color: "#fff" }}>Delete</button>
    </div>
  ) : (
    <p>Loading...</p>
  );
}
